  v_plan jsonb;
  v_day jsonb;
  v_plan_id uuid;
  v_day_id uuid;
  v_focus_label text;
begin
  for v_plan in
    select value
    from jsonb_array_elements($plans$
[
  {
    "id": "90000000-0000-0000-0000-000000000201",
    "title": "Practice of God's Presence",
    "description": "A 4-day plan drawn from Brother Lawrence's public-domain devotional classic on meeting God in ordinary work, prayer, weakness, and love.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "God's presence",
    "tags": ["presence", "prayer", "ordinary-life"],
    "days": [
      {"day_number": 1, "title": "God in the Ordinary", "summary": "Brother Lawrence begins with the simple conviction that God can be known in common tasks as surely as in secluded devotion.", "references": ["Psalms 16:8", "Colossians 3:17"]},
      {"day_number": 2, "title": "Prayer Without Leaving the Kitchen", "summary": "Daily labor becomes a place of prayer when the heart learns to turn toward God in the middle of interruption and duty.", "references": ["1 Thessalonians 5:17", "Luke 10:38-42"]},
      {"day_number": 3, "title": "Returning After Distraction", "summary": "His counsel on wandering thoughts is gentle and practical: return to God promptly, quietly, and without self-torment.", "references": ["Psalms 73:23-26", "Hebrews 4:16"]},
      {"day_number": 4, "title": "Love as Continual Recollection", "summary": "The goal is not strained intensity but a loving, steady recollection of God that keeps the soul abiding in Christ.", "references": ["John 15:4-5", "John 14:23"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000202",
    "title": "Following Christ in Humility",
    "description": "A 4-day plan based on Thomas a Kempis' public-domain devotional classic, tracing the humble, hidden, cross-shaped way of following Christ.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "humble obedience",
    "tags": ["humility", "discipleship", "holiness"],
    "days": [
      {"day_number": 1, "title": "Learn of Christ", "summary": "The opening movement fixes attention on Christ Himself, whose meekness teaches the heart how true greatness is formed.", "references": ["Matthew 11:29", "John 13:15"]},
      {"day_number": 2, "title": "The Hidden Life Before God", "summary": "Thomas a Kempis presses the soul away from display and back toward the secret life of contentment, surrender, and inward devotion.", "references": ["Psalms 131:1-3", "Colossians 3:1-3"]},
      {"day_number": 3, "title": "Bearing the Cross", "summary": "The Christian path is not escape from difficulty but fellowship with Christ in self-denial, endurance, and obedient love.", "references": ["Luke 9:23", "Philippians 3:10"]},
      {"day_number": 4, "title": "Desire God Above All", "summary": "The plan closes by reordering desire so that God Himself is loved above comfort, praise, possession, and passing delight.", "references": ["Psalms 73:25-26", "John 12:26"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000203",
    "title": "Abide in the Vine",
    "description": "A 5-day plan adapted from Andrew Murray's public-domain classic on abiding in Christ through dependence, love, fruitfulness, and perseverance.",
    "total_days": 5,
    "completions": 0,
    "focus_label": "abiding in Christ",
    "tags": ["abiding", "jesus", "fruitfulness"],
    "days": [
      {"day_number": 1, "title": "The Call to Abide", "summary": "Murray opens with Christ's invitation to remain in Him as the foundation of the whole Christian life.", "references": ["John 15:1-5"]},
      {"day_number": 2, "title": "Dependence, Not Strain", "summary": "Abiding grows not by self-pressure but by glad dependence on the life of Christ working within the believer.", "references": ["Galatians 2:20", "Philippians 2:13"]},
      {"day_number": 3, "title": "Fruit Through Union", "summary": "Real fruitfulness is the overflow of union with Christ rather than the result of restless religious effort.", "references": ["John 15:7-8", "Colossians 2:6-7"]},
      {"day_number": 4, "title": "Abiding in Love", "summary": "The life of abiding is also the life of remaining in Christ's love, where obedience and joy belong together.", "references": ["John 15:9-11", "Romans 8:35-39"]},
      {"day_number": 5, "title": "Persevering in the Vine", "summary": "The final day looks to the keeping power of God, urging perseverance by fixing the eyes on Christ from start to finish.", "references": ["Jude 24-25", "Hebrews 12:1-2"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000204",
    "title": "Waiting Well",
    "description": "A 5-day plan drawn from Andrew Murray's public-domain meditations on waiting on God in trust, weakness, shared prayer, and obedience.",
    "total_days": 5,
    "completions": 0,
    "focus_label": "waiting on God",
    "tags": ["waiting", "trust", "prayer"],
    "days": [
      {"day_number": 1, "title": "Why Wait?", "summary": "Murray frames waiting on God not as passivity but as a posture of faith that expects Him to act in His own wisdom.", "references": ["Psalms 27:14", "Lamentations 3:25-26"]},
      {"day_number": 2, "title": "Waiting in Weakness", "summary": "Neediness becomes a fitting place for hope when the believer learns to expect strength from the Lord rather than from self.", "references": ["Isaiah 40:29-31", "2 Corinthians 12:9-10"]},
      {"day_number": 3, "title": "Waiting in Trust", "summary": "The soul learns to wait with expectancy, resting on the character of God even when answers seem delayed.", "references": ["Psalms 130:5-6", "Micah 7:7"]},
      {"day_number": 4, "title": "Waiting Together", "summary": "Murray also treats waiting as a shared life of prayer in which the people of God look upward with one heart.", "references": ["Psalms 123:1-2", "Acts 1:14"]},
      {"day_number": 5, "title": "Waiting That Ends in Obedience", "summary": "True waiting is completed in responsive action, where trust becomes concrete obedience rather than spiritual delay.", "references": ["Psalms 37:7", "James 1:22"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000205",
    "title": "The Way Downward",
    "description": "A 4-day plan based on Andrew Murray's public-domain classic on humility, Christlike lowliness, and surrender before God and others.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "humility",
    "tags": ["humility", "surrender", "christlikeness"],
    "days": [
      {"day_number": 1, "title": "Humility Before God", "summary": "The first step downward is to bow before the high and holy God who draws near to the contrite.", "references": ["Isaiah 57:15", "James 4:6-10"]},
      {"day_number": 2, "title": "Christ's Lowliness", "summary": "Christ's own self-emptying is held up as the pattern and power for every truly humble life.", "references": ["Philippians 2:5-8", "Matthew 11:29"]},
      {"day_number": 3, "title": "Humility in Community", "summary": "Murray turns humility outward, teaching believers to think soberly of themselves and to honor others above self.", "references": ["Romans 12:3", "Philippians 2:3-4"]},
      {"day_number": 4, "title": "Exaltation Through Surrender", "summary": "The closing day remembers that the way down is also the way God lifts up those who entrust themselves to Him.", "references": ["Luke 14:11", "1 Peter 5:5-6"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000206",
    "title": "Learn to Pray",
    "description": "A 5-day plan adapted from Andrew Murray's public-domain teaching on prayer as a life learned from Christ in dependence, truth, and persistence.",
    "total_days": 5,
    "completions": 0,
    "focus_label": "prayer",
    "tags": ["prayer", "jesus", "discipleship"],
    "days": [
      {"day_number": 1, "title": "Why Christ Must Teach Prayer", "summary": "Prayer begins with the humble recognition that we need Jesus Himself to school us in asking, trusting, and abiding.", "references": ["Luke 11:1-4"]},
      {"day_number": 2, "title": "In Spirit and Truth", "summary": "Murray ties prayer to the inward work of the Spirit, who teaches believers to approach the Father sincerely and deeply.", "references": ["John 4:23-24", "Romans 8:26-27"]},
      {"day_number": 3, "title": "The Father's Priorities First", "summary": "The Lord's Prayer trains the heart to begin with the Father's name, kingdom, and will before personal requests.", "references": ["Matthew 6:9-10"]},
      {"day_number": 4, "title": "Asking in Christ's Name", "summary": "To ask in Christ's name is to pray in union with His will, confidence, and mediating grace.", "references": ["John 14:13-14", "John 16:23-24"]},
      {"day_number": 5, "title": "Prayer as School, Not Technique", "summary": "The last day treats prayer as a lifelong practice of watchfulness and communion, not a shortcut to quick results.", "references": ["Ephesians 6:18", "Colossians 4:2"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000207",
    "title": "Christ Within",
    "description": "A 4-day plan based on Andrew Murray's public-domain meditations on Christ dwelling within the believer as life, rest, surrender, and power.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "Christ within",
    "tags": ["indwelling", "jesus", "surrender"],
    "days": [
      {"day_number": 1, "title": "Christ Our Life Within", "summary": "Murray starts with the astonishing promise that Christ is not merely before us as example but within us as life.", "references": ["Colossians 1:27", "Galatians 2:20"]},
      {"day_number": 2, "title": "Waiting on God in the Inner Life", "summary": "The inward life deepens as the soul learns quiet dependence and yields itself to the Spirit's leading.", "references": ["Psalms 62:1-2", "Romans 8:14"]},
      {"day_number": 3, "title": "Surrender and Rest", "summary": "Rest grows where the heart lays down self-rule and presents itself wholly to God.", "references": ["Matthew 11:28-30", "Romans 12:1-2"]},
      {"day_number": 4, "title": "The Source of Power in Prayer", "summary": "Power in prayer rises from Christ abiding within, shaping desire and giving holy boldness before the Father.", "references": ["Ephesians 3:16-21", "John 15:7"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000208",
    "title": "Power in Prayer",
    "description": "A 4-day plan adapted from E. M. Bounds' public-domain classic on prayer as the hidden source of spiritual power and fruitful service.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "prayerful power",
    "tags": ["prayer", "ministry", "power"],
    "days": [
      {"day_number": 1, "title": "Prayer Before Method", "summary": "Bounds insists that spiritual effectiveness is born from prayer before it is supported by planning, talent, or method.", "references": ["Acts 6:4", "Mark 1:35"]},
      {"day_number": 2, "title": "The Praying Minister and Worker", "summary": "Those who serve others need more than activity; they need the secret work of intercession and nearness to God.", "references": ["James 5:16-18", "1 Timothy 2:1-2"]},
      {"day_number": 3, "title": "Prayer and Spiritual Power", "summary": "Bounds links believing prayer with bold expectation that God acts beyond visible strength and human sufficiency.", "references": ["Mark 11:24", "John 14:12-14"]},
      {"day_number": 4, "title": "Power That Flows from Hidden Communion", "summary": "The final emphasis is simple and searching: lasting power flows from a hidden life with God.", "references": ["Luke 18:1", "Colossians 4:12"]}
    ]
  }
]
$plans$::jsonb)
  loop
    v_plan_id := (v_plan ->> 'id')::uuid;

    if exists (select 1 from public.devotional_plans where id = v_plan_id) then
      continue;
    end if;

    insert into public.devotional_plans (
      id, title, description, cover_image, completions, tags, status, total_days, author_id, created_at, updated_at
    )
    values (
      v_plan_id,
      v_plan ->> 'title',
      v_plan ->> 'description',
      null,
      coalesce((v_plan ->> 'completions')::int, 0),
      array(select jsonb_array_elements_text(v_plan -> 'tags')),
      'published',
      (v_plan ->> 'total_days')::int,
      null,
      v_now,
      v_now
    );

    v_focus_label := coalesce(nullif(v_plan ->> 'focus_label', ''), lower(v_plan ->> 'title'));

    for v_day in
      select value
      from jsonb_array_elements(v_plan -> 'days')
    loop
      insert into public.devotional_days (
        plan_id, day_number, content, title, created_at, updated_at
      )
      values (
        v_plan_id,
        (v_day ->> 'day_number')::int,
        format(
          '<p>%s</p><p>Ask God to deepen %s in you today, then take one concrete step of obedience before the day ends.</p>',
          v_day ->> 'summary',
          v_focus_label
        ),
        v_day ->> 'title',
        v_now,
        v_now
      )
      returning id into v_day_id;

      insert into public.scripture_references (
        user_id, day_id, reference, created_at, updated_at
      )
      values (
        null,
        v_day_id,
        array(select jsonb_array_elements_text(v_day -> 'references')),
        v_now,
        v_now
      );
    end loop;
  end loop;
end
$$;
do $$
declare
  v_now constant timestamptz := timestamptz '2026-04-14 12:00:00+00';
  v_plan_id constant uuid := '90000000-0000-0000-0000-000000000102';
  v_day int;
  v_day_id uuid;
  v_month int;
  v_morning_idx int;
  v_evening_idx int;
  v_month_theme text[] := array[
    'the mercy of Christ that meets a new beginning',
    'quiet repentance and renewed desire',
    'steady trust when the path feels uncertain',
    'resurrection hope that turns ordinary days holy',
    'the love of God expressed in practical obedience',
    'patient endurance when strength feels thin',
    'life in the Spirit and watchful prayer',
    'wisdom for decisions, speech, and hidden motives',
    'humility that receives correction without despair',
    'joyful witness in work, family, and neighborliness',
    'gratitude for daily bread and undeserved kindness',
    'hope for the kingdom that is coming'
  ];
  v_morning_opening text[] := array[
    'Open the day by giving your first attention to Jesus.',
    'Before the noise gathers, remember that Christ is already near.',
    'Begin with Scripture and let truth set the pace of your thoughts.',
    'Offer your plans to God before you try to master them yourself.',
    'Choose watchfulness, because small compromises are easier to prevent than to repair.',
    'Ask for courage to obey in the ordinary places you will walk today.',
    'Receive today as a gift, not as something you must secure by anxious striving.'
  ];
  v_evening_closing text[] := array[
    'As night arrives, lay every unfinished burden back into the hands of God.',
    'Review the day with honesty, and receive mercy where you stumbled.',
    'Give thanks for hidden kindnesses you would have missed without reflection.',
    'Let the Scriptures quiet your mind more than your circumstances disturb it.',
    'Release the people you carry in worry, and entrust them to the care of Jesus.',
    'End the day in hope: grace has been at work even where you could not see it.',
    'Rest as a beloved child, not as a worker who must keep proving worth.'
  ];
  v_morning_title text[] := array[
    'Fresh Mercy',
    'Watchful Prayer',
    'Steady Trust',
    'Simple Obedience',
    'Holy Wisdom',
    'Courage for Today',
    'Joyful Dependence'
  ];
  v_evening_title text[] := array[
    'Resting in Peace',
    'Mercy for the Heart',
    'Quiet Thanksgiving',
    'Hope in the Dark',
    'Released Burdens',
    'Hidden Faithfulness',
    'Evening Worship'
  ];
  v_month_ref text[] := array[
    'Psalm 5:3',
    'Mark 1:35',
    'Isaiah 26:3',
    'John 15:4',
    'Psalm 119:105',
    'James 4:8',
    'Galatians 5:16',
    'Philippians 4:6-7',
    'Micah 6:8',
    'Romans 12:12',
    '1 Thessalonians 5:18',
    'Revelation 22:20'
  ];
  v_evening_ref text[] := array[
    'Psalm 4:8',
    'Lamentations 3:22-23',
    'Matthew 11:28',
    'Psalm 130:5',
    '1 John 1:9',
    'Hebrews 13:8',
    'Psalm 121:4'
  ];
begin
  if exists (select 1 from public.devotional_plans where id = v_plan_id) then
    return;
  end if;

  insert into public.devotional_plans (
    id, title, description, cover_image, completions, tags, status, total_days, author_id, created_at, updated_at
  )
  values (
    v_plan_id,
    'Morning and Evening',
    'A yearlong adaptation of C.H. Spurgeon''s classic public-domain devotional, pairing a morning posture of attention with an evening posture of rest in one daily reflection for the app.',
    null,
    0,
    array['classic', 'scripture', 'daily-rhythm', 'pastoral'],
    'published',
    366,
    null,
    v_now,
    v_now
  );

  for v_day in 1..366 loop
    v_month := extract(month from (date '2024-01-01' + (v_day - 1)))::int;
    v_morning_idx := ((v_day - 1) % 7) + 1;
    v_evening_idx := ((v_day + 2) % 7) + 1;

    insert into public.devotional_days (
      plan_id, day_number, content, title, created_at, updated_at
    )
    values (
      v_plan_id,
      v_day,
      format(
        '<p><strong>Morning:</strong> %s Let %s shape the way you pray, work, and respond today.</p><p><strong>Evening:</strong> %s Review the day with honesty, receive Christ''s mercy, and rest in His keeping.</p>',
        v_morning_opening[v_morning_idx],
        v_month_theme[v_month],
        v_evening_closing[v_evening_idx]
      ),
      format('%s / %s', v_morning_title[v_morning_idx], v_evening_title[v_evening_idx]),
      v_now,
      v_now
    )
    returning id into v_day_id;

    insert into public.scripture_references (
      user_id, day_id, reference, created_at, updated_at
    )
    values (
      null,
      v_day_id,
      array[v_month_ref[v_month], v_evening_ref[v_evening_idx]],
      v_now,
      v_now
    );
  end loop;
end
$$;

do $$
declare
  v_now constant timestamptz := timestamptz '2026-04-14 12:00:00+00';
  v_plan jsonb;
  v_day jsonb;
  v_plan_id uuid;
