begin
  for v_plan in
    select value
    from jsonb_array_elements($plans$
[
  {
    "id": "90000000-0000-0000-0000-000000000209",
    "title": "Why Prayer Matters",
    "description": "A 4-day plan based on E. M. Bounds' public-domain reflections on prayer as alignment with God's purposes in intercession, history, and kingdom work.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "purposeful prayer",
    "tags": ["prayer", "purpose", "intercession"],
    "days": [
      {"day_number": 1, "title": "Prayer Aligns with God's Purposes", "summary": "Bounds opens by treating prayer as participation in what God intends to do rather than as an attempt to bend Him to us.", "references": ["Matthew 6:10", "1 John 5:14-15"]},
      {"day_number": 2, "title": "Moses and Intercessory Purpose", "summary": "The life of Moses shows prayer at work inside covenant history, where pleading before God becomes part of His saving action.", "references": ["Exodus 32:11-14", "Deuteronomy 9:18-20"]},
      {"day_number": 3, "title": "Elijah and Prevailing Prayer", "summary": "Elijah demonstrates that fervent prayer is not dramatic performance but faith-filled dependence on the living God.", "references": ["1 Kings 18:36-39", "James 5:17-18"]},
      {"day_number": 4, "title": "Prayer as Kingdom Labor", "summary": "The closing day frames prayer as real labor for the kingdom, especially in the work of gospel fruitfulness and spiritual endurance.", "references": ["Luke 10:2", "Colossians 1:9-12"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000210",
    "title": "Prayer's Reach",
    "description": "A 4-day plan drawn from E. M. Bounds' public-domain work on the breadth of prayer across promise, mission, expectancy, and God's power.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "expectant prayer",
    "tags": ["prayer", "promises", "mission"],
    "days": [
      {"day_number": 1, "title": "The Wide Range of Prayer", "summary": "Bounds invites the reader to see prayer as broad and bold, reaching into every arena where God invites faith.", "references": ["Matthew 21:22", "John 15:7"]},
      {"day_number": 2, "title": "Prayer and God's Promises", "summary": "God's promises steady prayer, giving the believer warrant for hope rather than room for spiritual presumption.", "references": ["2 Peter 1:4", "Hebrews 10:23"]},
      {"day_number": 3, "title": "Prayer, Mission, and History", "summary": "Prayer is woven into the advance of the gospel, the courage of the church, and the outworking of God's purposes in history.", "references": ["Acts 4:29-31", "Revelation 8:3-4"]},
      {"day_number": 4, "title": "Prayer and Holy Expectancy", "summary": "The final note is expectancy: ask largely because God is able to do far more than the praying heart can imagine.", "references": ["Ephesians 3:20-21", "Psalms 81:10"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000211",
    "title": "Saved by Grace",
    "description": "A 4-day plan adapted from Charles Spurgeon's public-domain gospel classic on grace, faith, welcome, and assurance in Christ.",
    "total_days": 4,
    "completions": 0,
    "focus_label": "grace",
    "tags": ["grace", "faith", "salvation"],
    "days": [
      {"day_number": 1, "title": "Salvation Is All of Grace", "summary": "Spurgeon begins by shutting every door to self-salvation and opening wide the mercy of God in Christ.", "references": ["Ephesians 2:8-9", "Titus 3:4-7"]},
      {"day_number": 2, "title": "Faith Receives, Not Earns", "summary": "Faith is presented not as merit but as the empty hand that receives the righteousness and mercy of Christ.", "references": ["Romans 3:21-26", "Philippians 3:9"]},
      {"day_number": 3, "title": "Christ Welcomes the Sinner", "summary": "The plan turns directly toward the sinner with Christ's own promise that those who come to Him will not be cast out.", "references": ["John 6:37", "Luke 18:13-14"]},
      {"day_number": 4, "title": "Assurance Flows from Christ's Sufficiency", "summary": "The closing comfort rests not in fluctuating feeling but in the finished, ongoing sufficiency of Christ.", "references": ["Romans 8:1", "Hebrews 7:25"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000212",
    "title": "Promise-Driven Faith",
    "description": "A 5-day plan selected from Charles Spurgeon's public-domain daily promise book on fear, provision, trial, and perseverance.",
    "total_days": 5,
    "completions": 0,
    "focus_label": "God's promises",
    "tags": ["promises", "faith", "perseverance"],
    "days": [
      {"day_number": 1, "title": "God's First Promise", "summary": "The opening day traces the believer's confidence back to God's first gospel promise and the certainty that every promise finds its yes in Christ.", "references": ["Genesis 3:15", "2 Corinthians 1:20"]},
      {"day_number": 2, "title": "Strength for Fear", "summary": "Promise-grounded faith learns to answer fear by returning to God's presence, help, and unchanging care.", "references": ["Isaiah 41:10", "Psalms 56:3-4"]},
      {"day_number": 3, "title": "Provision and Sufficiency", "summary": "Spurgeon teaches the soul to expect that the God who calls will also supply what is truly needful.", "references": ["Philippians 4:19", "Psalms 84:11"]},
      {"day_number": 4, "title": "Presence in Trial", "summary": "Trial becomes endurable when the heart is steadied by the promise that God will neither leave nor forsake His people.", "references": ["Hebrews 13:5-6", "Psalms 46:1"]},
      {"day_number": 5, "title": "Promise-Grounded Perseverance", "summary": "The final day looks ahead with confidence because the God who gave His Son will also keep His people to the end.", "references": ["Jude 24", "Romans 8:32"]}
    ]
  },
  {
    "id": "90000000-0000-0000-0000-000000000213",
    "title": "Morning Mercies",
